<template><article class="card repair-card" :class="{clickable:canOpen}" @click="onOpen"><div class="repair-main"><h3>{{repair.title}}</h3><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · {{new Date(repair.created_at).toLocaleString()}}</small><small v-if="repair.status==='cancelled' && repair.cancelled_at" class="cancel-time">业主已于 {{new Date(repair.cancelled_at).toLocaleString()}} 撤销工单</small></div><div class="repair-side"><RepairStatusBadge :status="repair.status"/><el-button v-if="canCancel" link type="danger" size="small" :loading="cancelling" @click.stop="onCancel">撤销工单</el-button><el-button v-if="canOpen" link type="primary" size="small" @click.stop="onOpen">详情</el-button></div></article></template><script setup lang="ts">import type{Repair}from'../../types';import RepairStatusBadge from'./RepairStatusBadge.vue';const p=defineProps<{repair:Repair;canCancel?:boolean;cancelling?:boolean;canOpen?:boolean}>();const emit=defineEmits<{(e:'cancel'):void;(e:'open'):void}>();function onCancel(){emit('cancel')}function onOpen(){if(p.canOpen!==false)emit('open')}</script>
